# Your improved function here
def _makespan(self, sequence, proc_times_matrix):
    """
    Improved flow-shop makespan calculator.

    - Caches a flattened row-major list of processing times per matrix object
      (keyed by id and shape) to reduce indexing overhead.
    - Uses local variables and tight loops for speed.
    - Validates inputs and provides clearer error messages.
    - Robust to numpy arrays and nested Python lists/tuples/iterables.

    Returns the makespan (float) for the given job sequence.
    """
    m = int(getattr(self, "num_machines", 0))
    if m <= 0:
        return 0.0

    if not sequence:
        return 0.0

    # Prepare cache on the instance
    cache = getattr(self, "_proc_flat_cache", None)
    if cache is None:
        cache = self._proc_flat_cache = {}

    # Use id and shape (if available) as a cache key to reduce accidental collisions
    key = (id(proc_times_matrix), getattr(proc_times_matrix, "shape", None))
    rows_flat = cache.get(key)

    if rows_flat is None:
        # Build flattened list (row-major: job0_m0, job0_m1, ..., job1_m0, ...)
        flat = []
        try:
            # Prefer numpy-style ravel() if available
            ravel = getattr(proc_times_matrix, "ravel", None)
            if callable(ravel):
                # ravel() returns a numpy array; convert to list of floats
                flat = list(map(float, ravel().tolist()))
            else:
                # Generic iterable-of-iterables path
                for row in proc_times_matrix:
                    # Convert each element to float to ensure numeric operations are safe
                    for x in row:
                        flat.append(float(x))
        except Exception:
            # Fallbacks for strange matrix-like objects
            try:
                rows_count = proc_times_matrix.shape[0]
                for i in range(rows_count):
                    for x in proc_times_matrix[i]:
                        flat.append(float(x))
            except Exception:
                for row in proc_times_matrix:
                    for x in row:
                        flat.append(float(x))

        cache[key] = flat
        rows_flat = flat

    prev = [0.0] * m
    flat_len = len(rows_flat)

    for idx in sequence:
        try:
            i = int(idx)
        except Exception:
            raise ValueError(f"Sequence contains non-integer index: {idx!r}")

        if i < 0:
            raise IndexError(f"Job index out of range (negative): {i}")

        base = i * m
        if base + m > flat_len:
            raise IndexError(f"Job index {i} is out of range for the processing-times matrix")

        # Machine 0
        last = prev[0] + rows_flat[base]
        prev[0] = last

        # Machines 1..m-1
        j = 1
        while j < m:
            pj = rows_flat[base + j]
            pj_prev = prev[j]
            # start time = max(last_completion_on_previous_machine, completion_on_same_machine)
            if pj_prev < last:
                cur = last + pj
            else:
                cur = pj_prev + pj
            prev[j] = cur
            last = cur
            j += 1

    return float(prev[-1])
